                if cell.revealed:
                    if cell.mine:
                        btn.config(text=MINE, bg="#FF0000", relief=tk.SUNKEN,
                                   state=tk.DISABLED, disabledforeground="#000000")
                    else:
                        btn.config(relief=tk.SUNKEN, bg=REVEALED_BG, state=tk.DISABLED,
                                   text=str(cell.adjacent) if cell.adjacent else "",
                                   fg=NUMBER_COLORS.get(cell.adjacent, "#000000"),
                                   disabledforeground=NUMBER_COLORS.get(cell.adjacent, "#000000"))
                elif cell.flagged:
                    btn.config(text=FLAG, bg=FLAG_BG, fg="#CC0000", relief=tk.RAISED,
                               state=tk.NORMAL)
                else:
                    btn.config(text="", bg=COVERED_BG, relief=tk.RAISED, state=tk.NORMAL)
        remaining = self.board.mine_count - self.board.flags_used()
        self.mine_label.config(text=str(max(-99, min(999, remaining))).zfill(3) if remaining >= 0 else "-" + str(abs(remaining)).zfill(2))
